diff --git a/tests/web/e2e/U4/agent-1.spec.ts b/tests/web/e2e/U4/agent-1.spec.ts
new file mode 100644
index 00000000..31cccab3
--- /dev/null
+++ b/tests/web/e2e/U4/agent-1.spec.ts
@@ -0,0 +1,94 @@
+// AGENT-1 · Who touched what. Per node: each commit's `Agent` trailer beside the agent the hook saw make it, with the
+// match ✓/✗ (the README table). On the `agents` fixture trail (agents/README.md): c5 is trailered builder and was
+// logged by main (✗); c4 is builder on both sides (✓); c0 (build/F0a, git-only) has no hook record, drawn as a gap,
+// never as a match. The commit page's "trailer agent vs hook agent" region and the node page's "who touched what"
+// table. Parity on the design fixture against docs/ui/derived/U4/{commit,node}/.
+import { expect, test } from '@playwright/test';
+import type { Page } from '@playwright/test';
+import {
+  TRAILER_VS_HOOK,
+  WHO_TOUCHED,
+  auditEverywhere,
+  compileAgents,
+  openRegion,
+  region,
+  route,
+  shaOf,
+  short,
+} from './support/app';
+import type { CompiledTrail } from './support/app';
+import { commit, expectRegionComponents, node } from './support/parity';
+
+let fixture: CompiledTrail;
+test.beforeAll(() => {
+  fixture = compileAgents();
+});
+test.afterAll(() => {
+  fixture?.trail.cleanup();
+});
+
+const openCommit = (page: Page, id: string) => openRegion(page, fixture, route.commit(short(shaOf(fixture, id))), TRAILER_VS_HOOK);
+
+test.describe('the commit page', () => {
+  test('AGENT-1 · a commit the hook saw its trailer agent make shows builder beside builder, marked ✓', async ({ page }) => {
+    const found = await openCommit(page, 'c4');
+    await expect(found).toContainText('builder');
+    await expect(found).toContainText('✓');
+    await expect(found).not.toContainText('✗');
+  });
+
+  test('AGENT-1 · a commit trailered builder that the hook saw main make shows both, marked ✗', async ({ page }) => {
+    const found = await openCommit(page, 'c5');
+    await expect(found).toContainText('builder');
+    await expect(found).toContainText('main');
+    await expect(found).toContainText('✗');
+    await expect(found).not.toContainText('✓');
+  });
+
+  test('AGENT-1 · a commit with no hook record says so, with neither ✓ nor ✗', async ({ page }) => {
+    const found = await openCommit(page, 'c0');
+    await expect(found).toContainText('main');
+    await expect(found).toContainText(/not recorded/i);
+    await expect(found).not.toContainText('✓');
+    await expect(found).not.toContainText('✗');
+  });
+
+  test('AGENT-1 · the commit page has no axe violation, light and dark, 1440 and 390', async ({ page }) => {
+    await openCommit(page, 'c5');
+    await auditEverywhere(page, route.commit(short(shaOf(fixture, 'c5'))), async (p) => {
+      await expect(region(p, TRAILER_VS_HOOK)).toContainText('✗');
+    });
+  });
+});
+
+test.describe('the node page', () => {
+  test("AGENT-1 · build/F1's who-touched-what lists its nine commits, each with both agents", async ({ page }) => {
+    const found = await openRegion(page, fixture, route.node('build', 'F1'), WHO_TOUCHED);
+    const rows = found.locator('tbody tr');
+    await expect(rows).toHaveCount(9);
+    for (const id of ['c1', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7', 'c8', 'c9']) {
+      await expect(found, `the table lists ${id}`).toContainText(short(shaOf(fixture, id)));
+    }
+  });
+
+  test("AGENT-1 · c5's row reads builder by trailer, main by the hook, ✗; c4's builder, builder, ✓", async ({ page }) => {
+    const found = await openRegion(page, fixture, route.node('build', 'F1'), WHO_TOUCHED);
+    const c5 = found.locator('tbody tr').filter({ hasText: short(shaOf(fixture, 'c5')) });
+    await expect(c5).toContainText('builder');
+    await expect(c5).toContainText('main');
+    await expect(c5).toContainText('✗');
+    const c4 = found.locator('tbody tr').filter({ hasText: short(shaOf(fixture, 'c4')) });
+    await expect(c4).toContainText('✓');
+    await expect(c4).not.toContainText('main');
+  });
+});
+
+test.describe('parity', () => {
+  test("AGENT-1 · parity: the commit page's trailer agent vs hook agent, its components", async ({ page }) => {
+    await expectRegionComponents(page, commit, TRAILER_VS_HOOK);
+  });
+
+  test("AGENT-1 · parity: the node page's who touched what, its components", async ({ page }) => {
+    await expectRegionComponents(page, node, WHO_TOUCHED);
+  });
+});
diff --git a/tests/web/e2e/U4/support/app.ts b/tests/web/e2e/U4/support/app.ts
new file mode 100644
index 00000000..bdae78c2
--- /dev/null
+++ b/tests/web/e2e/U4/support/app.ts
@@ -0,0 +1,80 @@
+// U4's routes and the `agents` fixture trail (tests/web/fixtures/trails/agents/README.md), on top of U3's, U1's and
+// U0b's helpers for the built app (vite preview on DOCKET_APP_PORT): serving trace data, themes, widths, axe and the
+// commit links. U4 builds the decisions, not-found and sessions screens, the activity page's agent lanes, the commit
+// page's trailer agent against the hook agent, the node page's who-touched-what, the about and rule pages'
+// verify-it-yourself commands, the overview's latest human decisions and the top bar's search
+// (docs/ui/derived/U4/derived.json).
+import type { Locator, Page } from '@playwright/test';
+import { compileFixture } from '../../U0b/support/trail';
+import type { CompiledTrail } from '../../U0b/support/trail';
+import { route as u3 } from '../../U3/support/app';
+
+export { REPO, auditEverywhere, openOnFixture, openRegion, region, shaOf, short, snapshotOf } from '../../U3/support/app';
+export type { CompiledTrail } from '../../U3/support/app';
+
+/** U4's routes (hash routing), with the earlier nodes' it links between. */
+export const route = {
+  ...u3,
+  overview: '/#/',
+  matrix: '/#/rules',
+  rule: (id: string): string => `/#/rules/${encodeURIComponent(id)}`,
+  commit: (sha: string): string => `/#/commits/${sha}`,
+  activity: (plan: string, node: string): string => `/#/plans/${plan}/${node}/activity`,
+  decisions: '/#/decisions',
+  session: (file: string): string => `/#/sessions/${file}`,
+};
+
+/** The fixture U4's behaviour tests run on. */
+export const AGENTS = 'agents';
+
+/** Compiles the `agents` fixture once for a spec file. */
+export function compileAgents(): CompiledTrail {
+  return compileFixture(AGENTS);
+}
+
+/** The `agents` fixture's one context snapshot, by its URL segment. */
+export const SESSION = '20261018-101500-f1-signed-off';
+
+/** The regions U4 builds, by their data-region slugs (docs/ui/derived/U4/<screen>/screen.json). */
+export const TRAILER_VS_HOOK = 'trailer-agent-vs-hook-agent';
+export const COMMIT_HEADER = 'commit-header-and-trailers';
+export const WHO_TOUCHED = 'who-touched-what';
+export const LANES = 'agent-lanes';
+export const DECISION_LIST = 'decision-list';
+export const LATEST_DECISIONS = 'latest-human-decisions';
+export const RE_VERIFY = 're-verify-with-git';
+export const VERIFY_RULE = 'verify-it-yourself';
+export const NOT_FOUND = 'what-was-asked-for-and-where-to-go';
+export const SESSION_OPEN = 'one-snapshot-open-at-its-own-url-sessions-file';
+
+/** The kit's human-decision rows in `scope`, each carrying its kind (pause-1, steer, pause-2, sign-off, merge). */
+export function decisionRows(scope: Locator): Locator {
+  return scope.locator('[class*="kit-human-decision-row__row"]');
+}
+
+/** The kind of each decision row in `scope`, in page order. */
+export async function decisionKinds(scope: Locator): Promise<string[]> {
+  return decisionRows(scope).evaluateAll((rows) => rows.map((row) => row.getAttribute('data-kind') ?? ''));
+}
+
+/** The agents of the lanes in `scope`, in page order, from each lane's "<agent> rungs" list. */
+export async function laneAgents(scope: Locator): Promise<string[]> {
+  return scope
+    .locator('ol[aria-label$=" rungs"]')
+    .evaluateAll((lists) => lists.map((list) => (list.getAttribute('aria-label') ?? '').replace(/ rungs$/, '')));
+}
+
+/** The top bar's search field (the kit's search: a combobox in a search landmark). */
+export function searchField(page: Page): Locator {
+  return page.getByRole('search').getByRole('combobox');
+}
+
+/** The matches the search shows. */
+export function searchOptions(page: Page): Locator {
+  return page.getByRole('search').getByRole('option');
+}
+
+/** A row of the who-touched-what table, by the short SHA its commit cell shows. */
+export function touchedRow(scope: Locator, shortSha: string): Locator {
+  return scope.locator('tbody tr').filter({ hasText: shortSha });
+}
diff --git a/tests/web/e2e/U4/support/parity.ts b/tests/web/e2e/U4/support/parity.ts
new file mode 100644
index 00000000..6f825314
--- /dev/null
+++ b/tests/web/e2e/U4/support/parity.ts
@@ -0,0 +1,93 @@
+// Parity with U4's derived reference (docs/ui/derived/U4/), the built routes served on the design fixture
+// (docs/ui/fixture/), so both sides read the same data. Structure only: the tagged regions in order, the catalogued
+// components in each, and tokens in place of literal colours. The reader is U0b's
+// (tests/web/e2e/U0b/support/reference.ts). A region a later node builds (in transit against U4's own derived.json,
+// ../../U0b/support/built.ts) is compared by its place only, so these checks keep holding as later nodes land.
+// Parity tests are the only ones, with reachability, that may pass at the stub.
+import { expect } from '@playwright/test';
+import type { BrowserContext, Page } from '@playwright/test';
+import { serveTrace, setTheme, themes, viewports } from '../../U0b/support/app';
+import { builtAt } from '../../U0b/support/built';
+import { literalColours, readBuilt, readReference as readFromU0b, regionNamed } from '../../U0b/support/reference';
+import type { Structure } from '../../U0b/support/reference';
+import { designFixtureDir } from '../../U0b/support/trail';
+import { route } from './app';
+
+export interface Screen {
+  label: string;
+  screen: string;
+  state: string;
+  path: string;
+}
+
+// Each reference's own data in the design fixture (docs/ui/screens/<screen>/screen.json, its states).
+export const decisions: Screen = { label: 'decisions page', screen: 'decisions', state: 'populated', path: route.decisions };
+export const notFound: Screen = { label: 'not-found page', screen: 'not-found', state: 'populated', path: '/#/no/such/page' };
+export const sessions: Screen = {
+  label: 'sessions page (f6-done-merged open)',
+  screen: 'sessions',
+  state: 'populated',
+  path: route.session('20261019-151542-f6-done-merged'),
+};
+export const activity: Screen = { label: 'activity page (build/F3)', screen: 'activity', state: 'populated', path: route.activity('build', 'F3') };
+export const commit: Screen = {
+  label: 'commit page (build/F3 3a092b0)',
+  screen: 'commit',
+  state: 'populated',
+  path: route.commit('3a092b06f4691f5cb5ee8ed117d4e755e2095545'),
+};
+export const node: Screen = { label: 'node page (build/F3)', screen: 'node', state: 'populated', path: route.node('build', 'F3') };
+export const about: Screen = { label: 'about page', screen: 'about', state: 'populated', path: route.about };
+export const rule: Screen = { label: 'rule page (GET-1)', screen: 'rule', state: 'populated', path: route.rule('GET-1') };
+export const overview: Screen = { label: 'overview', screen: 'overview', state: 'populated', path: route.overview };
+
+const { regionSettled } = builtAt('U4');
+
+/** Reads docs/ui/derived/U4/<screen>/<state>.html. U0b's reader joins docs/ui/derived/U0b with the screen given. */
+function readReference(context: BrowserContext, screen: string, state: string): Promise<Structure> {
+  return readFromU0b(context, `../U4/${screen}`, state);
+}
+
+async function open(page: Page, s: Screen): Promise<void> {
+  await serveTrace(page, designFixtureDir);
+  await setTheme(page, 'light');
+  await page.setViewportSize(viewports[1440]);
+  await page.goto(s.path);
+}
+
+/** The regions in page order: [slug, req, built] for a settled region, [slug] alone for one a later node builds. */
+function settledOrder(s: Structure, screen: string): (string | boolean)[][] {
+  return s.regions.map((r) => (regionSettled(screen, r.slug) ? [r.slug, r.req.join(' '), r.built] : [r.slug]));
+}
+
+/** Every region of the reference, in its order, with its data-req and whether it is built. */
+export async function expectRegionsInOrder(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => settledOrder(await readBuilt(page, reference), s.screen)).toEqual(settledOrder(reference, s.screen));
+}
+
+/** One region of the reference, with its data-req and the catalogued components inside it. */
+export async function expectRegionComponents(page: Page, s: Screen, slug: string): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  const wanted = regionNamed(reference, slug);
+  expect(wanted, `the reference has region ${slug}`).toBeDefined();
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const found = regionNamed(await readBuilt(page, reference), slug);
+      return found ? { req: found.req, comps: found.comps, built: found.built } : null;
+    })
+    .toEqual({ req: wanted?.req, comps: wanted?.comps, built: wanted?.built });
+}
+
+/** No colour on the page from a literal: the screen's styles, inline styles and SVG paint use tokens only. */
+export async function expectTokensOnly(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => (await readBuilt(page, reference)).regions.length).toBe(reference.regions.length);
+  for (const theme of themes) {
+    await setTheme(page, theme);
+    expect.soft(await page.evaluate(literalColours), `literal colours, ${theme}`).toEqual([]);
+  }
+}
